# 외전 출신마다 4장과 5장에 하나씩 더 찾아오는 일. 십 년 길의 끝이 보이는 때에 그 출신의 목표를 다시 건드린다.
from dsl import *
from bondkit import ex

ex("외전당가", "더_당가", [4, 5], "침을 갈아 끼우는 날", "동생의 침을 갈아 끼울 날이다. 가주가 놓은 침 서른여섯 대 가운데 셋이 검게 변했다. 남은 날이 생각보다 적다. 동생이 눈을 뜨고 묻는다. \"언니, 아직 멀었어?\"",
 [C("검게 변한 침을 내 손으로 갈아 끼운다", O("손이 떨리지 않았다. 셋을 갈아 끼우자 동생의 숨이 고르게 돌아왔다. 가주가 문밖에서 보고 있었다.", alignment=AL(j=30), stats={"mind": 4, "internal": 2})),
  C("검게 변한 침을 녹여 독의 흔적을 거꾸로 읽는다", O("침에 밴 독이 길을 가리켰다. 남쪽이다. 처방의 반쪽이 거기 있다.", alignment=AL(s=20), stats={"mind": 5})),
  C("동생의 피를 받아 독을 내 몸에 옮겨 시험한다", O("독이 내 핏줄을 탔다. 사흘을 앓았다. 그 사흘 동안 독의 성질을 몸으로 다 알았다.", alignment=AL(m=30), stats={"internal": 4}, hp_pct=-15))])

ex("외전빙궁", "더_빙궁", [4, 5], "궁주께 올릴 첫 줄", "십 년의 답을 정리하려 붓을 들었다. 첫 줄이 써지지 않는다. 중원에서 본 것은 너무 많고 답은 한마디여야 한다.",
 [C("중원에서 만난 사람들의 얼굴부터 적는다", O("얼굴을 적다 보니 답이 보였다. 문을 열어야 할 까닭도, 닫아야 할 까닭도 그 얼굴들에 있었다.", alignment=AL(j=20), stats={"mind": 5})),
  C("중원의 장터 값과 세력의 수를 셈해 적는다", O("셈은 정확했다. 그런데 셈으로는 답이 나오지 않았다.", alignment=AL(s=20), stats={"mind": 4})),
  C("붓을 꺾고 얼음 위에서 검을 펼친다", O("검이 먼저 답했다. 답은 검끝에 서리처럼 내려앉았다. 글은 그다음이다.", alignment=AL(m=10), stats={"martial": 4}))])

ex("외전매화", "더_매화", [4, 5], "스승의 초막에 핀 매화", "화산 뒷산 스승의 초막에 들렀다. 스승은 없다. 마당의 늙은 매화나무가 한겨울에 꽃을 피웠다. 꽃잎이 스물넷이다.",
 [C("꽃잎 스물넷을 검끝으로 하나씩 받는다", O("스물셋을 받았다. 마지막 하나는 받지 못했다. 스승이 남겨 둔 한 수가 그 꽃잎에 있었다.", alignment=AL(j=20), stats={"martial": 5})),
  C("초막을 쓸고 스승의 자리에 차를 올린다", O("찻물이 식을 때까지 앉아 있었다. 스승이 왜 열째 자리를 비웠는지 조금 알 것 같았다.", alignment=AL(j=10), stats={"mind": 5})),
  C("매화나무를 베어 스승을 끌어내리는 미끼로 삼는다", O("매화나무가 쓰러졌다는 소문이 퍼지면 스승이 올 것이다. 오지 않으면 그것도 답이다.", alignment=AL(m=40), stats={"mind": 3}))])

ex("외전살막", "더_살막", [4, 5], "장부의 남은 숫자", "곡 노인이 장부를 펼쳐 보인다. 몸값의 아홉 배까지 남은 숫자가 생각보다 적다. 곡 노인이 말한다. \"마지막 셋이 가장 무겁다. 셋 다 이름 있는 자다.\"",
 [C("셋의 이름을 받아 들고 그들이 어떤 자인지부터 캔다", O("셋 가운데 둘은 죽어 마땅한 자였다. 하나는 아니었다. 그 하나를 어찌할지는 아직 정하지 않았다.", alignment=AL(j=20), stats={"mind": 4})),
  C("셋을 하나씩 지운다", O("첫째가 지워졌다. 장부의 숫자가 줄었다. 칼이 조금 무거워졌다.", battle="살막살수", foe="장부에 적힌 첫째 이름 철갑수 하우", foe_line="\"살막의 칼이 찾아올 줄 알았다. 네 이름도 장부에 있더냐.\"", alignment=AL(s=20, m=10), silver=150, stats={"martial": 3})),
  C("곡 노인에게 장부를 다른 방법으로 닫을 길을 묻는다", O("곡 노인이 한참 웃었다. \"장부를 닫는 길은 두 가지다. 채우거나, 태우거나.\"", alignment=AL(s=10), stats={"mind": 3}))])

ex("외전수로", "더_수로", [4, 5], "아버지의 작살", "청교채 터 물속에서 아버지가 쓰던 작살창이 건져 올려졌다. 녹이 슬었다. 흩어졌던 물사람들이 하나둘 모여 창을 본다.",
 [C("녹을 벗기고 창을 다시 세운다", O("밤새 녹을 벗겼다. 새벽에 창끝이 빛났다. 물사람들이 그 빛을 보고 배를 띄웠다.", alignment=AL(j=20), stats={"external": 3, "mind": 2}, fame=10)),
  C("창을 총채주에게 보내 싸움을 걸어 온다", O("총채주는 창을 받고 답하지 않았다. 대신 그의 배들이 물길을 비켰다.", alignment=AL(s=20), stats={"mind": 3}, fame=5)),
  C("창을 물속에 다시 던지고 새 창을 잡는다", O("아버지의 수채는 끝났다. 이제 내 수채다. 물사람들이 놀랐다가 따라왔다.", alignment=AL(m=20), stats={"martial": 3}))])

ex("외전혈승", "더_혈승", [4, 5], "옛 터의 마지막 비석", "개조가 순례하던 옛 터 가운데 마지막 비석에 닿았다. 비석에 피로 쓴 글이 남았다. 백 년 전 개조가 무엇을 바랐는지 적혔다. 교주가 말한 것과 다르다.",
 [C("비석의 글을 베껴 교주에게 보인다", O("교주는 오래 비석의 글을 보았다. 그러고는 베낀 종이를 불에 넣었다. 그 얼굴을 잊지 못할 것이다.", alignment=AL(j=20), stats={"mind": 5})),
  C("비석의 글을 가사 안에 감추고 아무에게도 말하지 않는다", O("글은 내 가사 안에서 무거워졌다. 언젠가 꺼낼 날이 올 것이다.", alignment=AL(s=20), stats={"mind": 4})),
  C("비석을 부수고 교주의 말만 믿는다", O("비석이 무너졌다. 개조의 뜻은 교주가 말하는 그것이다. 이제 다른 뜻은 없다.", alignment=AL(m=40), stats={"external": 3}))])

ex("외전야수", "더_야수", [4, 5], "다섯째 영물의 발자국", "맹약을 맺을 영물이 하나 남았다. 밀림 깊은 곳에서 그 발자국을 찾았다. 발자국 곁에 사람의 발자국이 함께 있다. 신교의 내단 사냥꾼이다.",
 [C("사냥꾼보다 먼저 영물에게 닿는다", O("영물이 사냥꾼의 덫 앞에서 나를 보았다. 덫을 풀어 주자 영물이 다가왔다.", alignment=AL(j=30), stats={"mind": 4}, art_mastery={"경공": 8})),
  C("사냥꾼을 먼저 찾아 밀림에서 쫓아낸다", O("사냥꾼은 밀림의 길을 몰랐다. 사흘 만에 스스로 밀림을 떠났다.", battle="마교척살조", foe="다섯째 영물을 쫓는 신교의 내단 사냥꾼들", foe_line="\"영물은 먼저 잡는 자의 것이다.\"", alignment=AL(j=20), stats={"martial": 3})),
  C("사냥꾼이 영물을 지치게 할 때까지 기다린다", O("영물이 지쳤을 때 다가갔다. 맹약은 맺었다. 영물의 눈이 처음처럼 맑지는 않았다.", alignment=AL(m=30), stats={"mind": 3}))])

ex("외전소림", "더_소림", [4, 5], "산문 밖의 마지막 사본", "사라진 사본 열두 권 가운데 마지막 한 권의 행방을 들었다. 장터의 고서점이다. 주인은 그것이 소림의 것인 줄 모르고 땔감으로 쓰려 한다.",
 [C("값을 치르고 사본을 거둔다", O("주인이 헐값을 불렀다. 그대로 치렀다. 사본의 첫 장에 장경각의 인이 찍혀 있었다.", alignment=AL(j=30), stats={"mind": 4}, silver=-20)),
  C("주인에게 소림의 것이라 밝히고 돌려 달라 한다", O("주인이 놀라 사본을 내밀었다. 산문 밖에서도 소림의 이름은 통했다.", alignment=AL(j=20), stats={"mind": 3}, fame=5)),
  C("고서점 주인을 겁주어 사본을 사 간 다른 자의 이름까지 받아 낸다", O("주인이 떨며 이름 둘을 댔다. 사본을 노리는 자가 나 말고도 있었다.", alignment=AL(m=30), stats={"mind": 3})),
  C("사본을 먼저 읽고 산문에 가져갈지 정한다", O("밤새 읽었다. 사본에는 산문이 왜 닫혔는지에 대한 실마리가 있었다.", alignment=AL(s=20), stats={"mind": 5}))])

ex("외전무당", "더_무당", [4, 5], "돌문 너머의 기척", "폐관동 돌문 너머에서 처음으로 기척이 났다. 장문인이 움직였다. 두 사형에게 알려야 할까. 알리면 둘 다 돌문 앞으로 몰려올 것이다.",
 [C("두 사형에게 함께 알린다", O("두 사형이 돌문 앞에서 마주쳤다. 오랜만에 말없이 나란히 섰다.", alignment=AL(j=30), stats={"mind": 4})),
  C("아무에게도 알리지 않고 돌문을 더 굳게 지킨다", O("기척은 사흘 뒤 사라졌다. 장문인은 아직 나올 때가 아니었다.", alignment=AL(j=10), stats={"internal": 3, "mind": 2})),
  C("한 사형에게만 알려 다른 사형보다 먼저 서게 한다", O("한 사형이 먼저 돌문 앞에 섰다. 다른 사형은 나를 오래 보았다.", alignment=AL(s=20, m=10), stats={"mind": 3}))])

ex("외전아미", "더_아미", [4, 5], "남해의 배표", "남해로 가는 배표를 구했다. 홍란이 배표를 오래 들여다본다. \"이걸 타면 다시는 중원을 못 봐요.\" 붉은 소매를 자른 자리가 아직 붉다.",
 [C("배를 타기 전 그녀가 보고 싶은 곳에 들른다", O("홍란은 고향 마을의 우물을 보고 싶어 했다. 우물은 그대로였다. 그녀가 처음으로 웃었다.", alignment=AL(j=30), stats={"mind": 5})),
  C("배표를 한 장 더 사서 함께 가겠다고 한다", O("홍란이 배표 두 장을 겹쳐 들었다. 사태께 말씀드려야 한다고 했다.", alignment=AL(j=20), stats={"mind": 3}, silver=-30)),
  C("배표를 신교의 추적자에게 흘려 놓고 다른 배를 탄다", O("추적자들은 그 배를 쫓았다. 우리는 다른 배에 올랐다. 그 배의 다른 손님들이 어찌 되었는지는 모른다.", alignment=AL(m=30, s=10), stats={"mind": 4}))])

ex("외전공동", "더_공동", [4, 5], "보의 첫눈", "장성 아래 보에 첫눈이 내렸다. 겨울을 버틸 양식이 모자란다. 장문인 갈무진의 편지가 왔다. '눈이 내리면 돌아오라.' 보 사람들이 나를 본다.",
 [C("보에 남아 겨울을 함께 넘긴다", O("양식을 나누고 흙벽을 다시 쌓았다. 장문인께 답장을 썼다. 눈이 녹으면 가겠다고.", alignment=AL(j=30), stats={"external": 3, "mind": 2})),
  C("산문으로 돌아가 양식을 실어 온다", O("눈길을 왕복했다. 열흘이 걸렸다. 수레가 보에 닿던 날 아이들이 달려 나왔다.", alignment=AL(j=20), stats={"external": 4}, hp_pct=-8)),
  C("마적의 곳간을 털어 겨울 양식을 채운다", O("마적의 곳간은 넉넉했다. 보는 겨울을 넘길 것이다. 마적들은 넘기지 못할 것이다.", alignment=AL(m=30), stats={"martial": 3}, silver=40))])

ex("외전모용", "더_모용", [4, 5], "족보의 빈칸", "본가의 종손 어른이 족보를 펼쳐 보였다. 아버지의 이름이 들어갈 자리가 비어 있다. 그 아래 내 자리도 비어 있다. \"연운창을 들고 오면 붓을 들겠다.\"",
 [C("빈칸에 아버지의 이름만이라도 먼저 올려 달라 한다", O("종손 어른이 오래 붓을 들었다 놓았다. 끝내 아버지의 이름을 적었다. 내 자리는 비워 두었다.", alignment=AL(j=20), stats={"mind": 5})),
  C("연운창 없이 창 한 자루로 본가의 어른들과 겨루겠다고 한다", O("어른 셋과 겨뤘다. 셋째 어른이 창을 거두며 말했다. \"족보는 창이 적는 것이군.\"", alignment=AL(j=10), stats={"martial": 4}, fame=8)),
  C("족보를 찢고 내 이름으로 새 집안을 세우겠다고 한다", O("족보의 한 장이 찢어졌다. 종손 어른이 말없이 나를 보았다. 그 눈빛을 오래 잊지 못할 것이다.", alignment=AL(m=30), stats={"mind": 3}))])

ex("외전사도련", "더_사도련", [4, 5], "아비의 빚 한 줄", "추심당 장부의 아비 빚 한 줄 옆에 련주의 붉은 점이 찍혔다. 결산회에서 다룬다는 뜻이다. 마철이 귓속말을 한다. \"그 줄이 너를 련에 묶은 끈이다. 끊으면 너도 끝이다.\"",
 [C("빚을 내 손으로 갚아 끈을 끊는다", O("은자를 장부 위에 올렸다. 마철이 셈을 하고 줄을 그었다. 그날부터 련의 칼이 아니라 내 칼이다.", alignment=AL(j=20), silver=-200, stats={"mind": 4})),
  C("결산회 전에 장부의 그 줄을 다른 이름으로 옮겨 적는다", O("붓 한 번이었다. 빚은 다른 사람의 것이 되었다. 마철은 아무것도 보지 못한 척했다.", alignment=AL(s=40), stats={"mind": 3})),
  C("붉은 점을 찍은 자를 찾아 장부를 빼앗는다", O("장부를 쥔 자는 련주의 사람이었다. 그를 꺾자 장부가 내 손에 들어왔다. 련 전체가 나를 보게 되었다.", alignment=AL(m=30), stats={"martial": 4}, fame=10))])

ex("외전제갈", "더_제갈", [4, 5], "목우가 끄는 수레", "산길에서 목우가 끄는 수레를 보았다. 사람 없이 짐을 나른다. 설계도대로다. 수레에 실린 것은 신교의 군량이다. 목우는 아무것도 모른 채 걷는다.",
 [C("목우를 멈추고 설계도대로 다시 짜 마을의 짐을 나르게 한다", O("반나절 걸렸다. 목우가 방향을 틀어 산 아래 마을로 걸었다. 설계도를 그린 사람이 바란 것이 이것이었다.", alignment=AL(j=30), stats={"mind": 5})),
  C("목우의 짜임을 뜯어 보고 다시 맞춘다", O("뜯어 보니 설계도에 없는 쇠 하나가 끼워져 있었다. 누가 고친 것이다. 고친 손을 알면 설계도를 훔친 자를 안다.", alignment=AL(s=20), stats={"mind": 4})),
  C("목우를 부수고 군량을 불태운다", O("목우가 쓰러지고 군량이 탔다. 신교의 진영은 굶을 것이다. 산 아래 마을도 그 연기를 보았다.", alignment=AL(m=20, j=10), stats={"external": 3}))])

ex("외전귀문", "더_귀문", [4, 5], "어미의 등불", "등각의 수천 등불 가운데 하나가 흔들린다. 무령이 말한다. 어미의 혼이 묶인 등이다. 만혼제가 가까워질수록 흔들린다고 한다.",
 [C("등불 앞에 앉아 어미에게 말을 건다", O("등불은 대답하지 않았다. 그래도 밤새 흔들림이 잦아들었다.", alignment=AL(j=20), stats={"mind": 5})),
  C("만혼제의 순서를 캐어 어미의 등을 맨 끝으로 옮긴다", O("무령 몰래 순서를 바꿨다. 어미의 혼은 맨 마지막에 풀릴 것이다. 그때까지 내가 버티면 된다.", alignment=AL(s=20), stats={"mind": 4})),
  C("다른 등의 혼을 거두어 어미의 등을 밝힌다", O("다른 등 셋이 꺼졌다. 어미의 등이 밝아졌다. 꺼진 등의 주인들을 위해 우는 사람은 없었다.", alignment=AL(m=40), stats={"internal": 4}))])

ex("외전녹림", "더_녹림", [4, 5], "식구의 혼례", "흑송채의 식구 둘이 혼례를 올린다고 한다. 산채에 혼례는 처음이다. 술도 고기도 모자란다. 녹림왕의 회합이 코앞이다.",
 [C("관도의 상단을 털지 않고 장터에서 사 온다", O("은자가 많이 들었다. 혼례는 조촐했다. 식구들이 처음으로 산채가 집 같다고 했다.", alignment=AL(j=30), silver=-60, stats={"mind": 4})),
  C("이웃 산채에 혼례 음식을 꾸어 온다", O("이웃 채주가 웃으며 고기를 내주었다. 회합에서 그 빚을 갚아야 한다.", alignment=AL(s=20), stats={"mind": 3})),
  C("관도의 상단 하나를 털어 혼례를 크게 치른다", O("혼례는 사흘 동안 이어졌다. 관군이 산채를 노리기 시작했다.", alignment=AL(m=20, s=10), silver=40, fame=5))])

ex("외전흑사", "더_흑사", [4, 5], "아홉째 판의 판돈", "아홉째 판을 열 판돈이 모자란다. 늙은 판지기가 낡은 상자를 내민다. 평생 모은 것이라고 한다. \"판이 정직하게 돌면 갚게.\"",
 [C("판지기의 상자를 받고 정직한 판을 약조한다", O("상자는 가벼웠다. 그 무게만큼 판이 정직해야 한다.", alignment=AL(j=30), stats={"mind": 4}, silver=50)),
  C("상자를 돌려주고 다른 판주에게 돈을 빌린다", O("빌린 돈에는 이자가 붙었다. 판지기의 상자는 판지기의 것으로 남았다.", alignment=AL(s=20), silver=80, stats={"mind": 2})),
  C("판을 몰래 기울여 판돈을 불린다", O("판돈은 하룻밤에 세 배가 되었다. 판지기가 그것을 알고 상자를 거두어 갔다.", alignment=AL(m=20, s=20), silver=150))])

ex("외전망나니", "더_망나니", [4, 5], "서생의 누이", "벤 서생의 누이가 형장 앞에서 나를 기다렸다. 동생이 칼 아래에서 무슨 말을 했는지 묻는다.",
 [C("그가 남긴 말을 그대로 전한다", O("누이는 끝까지 들었다. 그러고는 고개를 숙였다. \"억울하다고 하지 않았군요.\" 그녀가 판결을 뒤집는 데 힘을 보태겠다고 했다.", alignment=AL(j=30), stats={"mind": 5})),
  C("누이에게 판결문을 쓴 자의 이름을 일러 준다", O("누이의 눈빛이 변했다. 그녀가 무엇을 할지는 알 수 없다.", alignment=AL(s=20), stats={"mind": 3})),
  C("아무 말도 하지 않고 칼을 씻으러 간다", O("누이가 등 뒤에서 오래 서 있었다. 칼을 씻는 물이 오래 붉었다.", alignment=AL(m=20), stats={"mind": 2}))])

ex("외전청성", "더_청성", [4, 5], "깨진 혼례의 패물", "깨진 혼례 날 사라졌던 신부의 패물이 장터에 나왔다. 당가의 가문 문양이 새겨진 비녀다. 판 자를 쫓으면 그날 밤 자객의 뒤를 알 수 있다.",
 [C("비녀를 사서 당가의 셋째 딸에게 돌려준다", O("셋째 딸이 비녀를 받고 울었다. 그날 밤 자객이 비녀를 노린 까닭을 털어놓았다.", alignment=AL(j=30), silver=-40, stats={"mind": 4})),
  C("판 자를 쫓아 자객의 뒤를 캔다", O("판 자는 장물아비였다. 그에게 비녀를 넘긴 자의 손에 붉은 실이 감겨 있었다고 한다.", alignment=AL(s=20), stats={"mind": 4})),
  C("비녀를 빼앗고 장물아비를 혼낸다", O("장물아비가 떨며 비녀를 내놓았다. 그가 아는 것은 많지 않았다.", alignment=AL(m=20), stats={"martial": 2}))])

ex("외전종남", "더_종남", [4, 5], "외당의 마지막 겨울", "외당의 검수들이 겨울을 넘길 장작이 없다. 사도련에 진 빚의 이자를 내느라 장작값까지 썼다. 산문에는 장작이 쌓여 있다. 장문인은 산문의 것을 외당에 내리지 않는다.",
 [C("산문에 올라 장문인께 직접 장작을 청한다", O("장문인이 오래 말이 없었다. 그러고는 산문의 장작 절반을 내렸다. \"외당이 종남이다.\"", alignment=AL(j=30), stats={"mind": 5})),
  C("산의 나무를 베어 외당의 장작을 만든다", O("이레 동안 도끼질을 했다. 손바닥이 갈라졌다. 외당은 겨울을 넘겼다.", alignment=AL(j=10), stats={"external": 4})),
  C("사도련의 장작 창고를 턴다", O("창고는 넉넉했다. 외당은 따뜻했다. 사도련의 장부에 이자 한 줄이 더 붙었다.", alignment=AL(m=20, s=10), stats={"martial": 2}, silver=20))])

ex("외전신교", "더_신교", [4, 5], "칼에 묶인 혼들의 밤", "칼이 밤마다 운다. 벤 자들의 혼이 묶인 칼이다. 마장의 칼보다 아직 가볍지만 잠을 잘 수 없다. 마장의 둘째 제자가 말한다. \"그 울음에 익숙해지면 칼이 네 것이 된다.\"",
 [C("칼을 내려놓고 혼들의 이름을 하나씩 부른다", O("다 부르지 못했다. 이름을 모르는 자가 있었다. 칼의 울음이 조금 잦아들었다.", alignment=AL(j=30), stats={"mind": 5})),
  C("울음을 견디며 칼을 품고 잔다", O("사흘째 밤 울음이 들리지 않았다. 익숙해진 것인지 귀가 닫힌 것인지 모른다.", alignment=AL(m=20), stats={"internal": 3, "mind": 2})),
  C("더 많은 혼을 묶어 울음을 덮는다", O("그날 밤 둘을 더 벴다. 울음은 덮이지 않았다. 더 커졌다.", alignment=AL(m=40), stats={"martial": 4}, hp_pct=-5))])

ex("외전홍수", "더_홍수", [4, 5], "금실 한 올", "붉은 옷의 여인이 소매에서 금실 한 올을 뽑아 내 앞에 놓았다. 소매에 금실을 달 자격을 시험하겠다고 한다. 시험은 교단을 떠나려는 소매 하나를 데려오는 일이다.",
 [C("떠나려는 소매를 만나 그녀의 사정을 듣는다", O("그녀는 아이를 낳았다. 교단에서 아이를 키울 수 없었다. 나는 그녀를 데려가지 않았다. 금실은 아직 탁자 위에 있다.", alignment=AL(j=30), stats={"mind": 5})),
  C("떠나려는 소매를 설득해 스스로 돌아오게 한다", O("말로 했다. 침은 쓰지 않았다. 그녀가 돌아왔다. 붉은 옷의 여인이 금실을 내 소매에 감았다.", alignment=AL(s=30), stats={"mind": 4}, fame=5)),
  C("떠나려는 소매를 침으로 잠재워 데려온다", O("소매는 잠든 채 돌아왔다. 붉은 옷의 여인이 웃었다. 금실이 소매에 감겼다. 무거웠다.", alignment=AL(m=40), stats={"martial": 3}))])

ex("외전점창", "더_점창", [4, 5], "벌레에 먹힌 마을의 아이", "독충의 진에 먹힌 마을에서 아이 하나가 살아 나왔다. 몸에 벌레가 기어 다닌 자국이 있다. 아이가 진의 기둥이 어디 있는지 안다고 한다. 벌레가 지나간 길을 기억한다고.",
 [C("아이를 산문에 맡기고 혼자 기둥을 찾는다", O("아이가 그려 준 길을 따라갔다. 기둥 하나를 찾았다. 아이는 산문에서 처음으로 깊이 잤다.", alignment=AL(j=30), stats={"mind": 3}, art_mastery={"경공": 8})),
  C("아이를 앞세워 기둥으로 간다", O("아이는 길을 정확히 알았다. 기둥 앞에서 아이가 떨었다. 무사히 돌아왔다. 아이는 그 뒤로 말이 없다.", alignment=AL(s=20), stats={"mind": 3}, final_weaken=5)),
  C("아이의 몸에 남은 벌레로 진의 독을 거꾸로 쓴다", O("아이의 몸에서 벌레를 꺼내 길렀다. 진의 독을 거꾸로 쓰는 법을 알았다. 아이는 그 일을 오래 무서워했다.", alignment=AL(m=30), stats={"internal": 3, "mind": 2}))])

ex("외전곤륜", "더_곤륜", [4, 5], "빙원의 지도", "북해로 가는 천 리 빙원의 지도를 손에 넣었다. 빙궁의 사람이 그린 것이다. 지도 한쪽에 '스물은 많다'는 글씨가 있다. 어린 제자 스물을 다 데려갈 수 없다는 뜻이다.",
 [C("스물 모두를 데려갈 길을 지도 위에 새로 긋는다", O("밤새 길을 그었다. 돌아가는 길이 열흘 늘었다. 스물이 다 갈 수 있는 길이다.", alignment=AL(j=30), stats={"mind": 5})),
  C("빙궁에 사람을 보내 스물을 다 받아 달라 청한다", O("빙궁의 답이 왔다. '오는 자는 막지 않는다. 오는 길은 책임지지 않는다.'", alignment=AL(s=20), stats={"mind": 3})),
  C("스물 가운데 버틸 수 있는 아이만 고른다", O("열둘을 골랐다. 나머지 여덟의 이름을 적은 종이를 오래 들고 있었다.", alignment=AL(m=30), stats={"mind": 4}))])

ex("외전광부", "더_광부", [4, 5], "갱도의 서른 개 표식", "무너진 갱도 입구에 갇혔던 서른의 이름을 새긴 표식이 섰다. 은방은 그 표식을 뽑으라 했다. 광부들이 표식을 지키며 나를 본다.",
 [C("표식 앞에 서서 은방의 감독관을 막는다", O("감독관이 패거리를 데려왔다. 표식은 그대로 섰다. 광부들이 그 앞에 돌을 하나씩 쌓았다.", battle="세가호위", foe="표식을 뽑으러 온 은방의 감독관 패거리", foe_line="\"돌덩이에 이름 새긴다고 은이 나오나.\"", alignment=AL(j=30), stats={"external": 3}, fame=8)),
  C("표식을 은방이 모르는 다른 갱도 안으로 옮긴다", O("표식은 깊은 갱도 안에 섰다. 은방은 찾지 못했다. 광부들은 일하러 들어갈 때마다 그 앞을 지났다.", alignment=AL(s=20), stats={"mind": 4})),
  C("은방의 장부에 서른의 이름을 써 넣고 값을 받아 낸다", O("은방은 값을 치렀다. 서른의 이름에 값이 매겨졌다. 광부들은 그 은자를 받으며 아무 말도 하지 않았다.", alignment=AL(m=20, s=20), silver=120))])

ex("외전사공", "더_사공", [4, 5], "방노삼의 마지막 노", "늙은 사공 방노삼이 더는 노를 젓지 못한다. 손이 떨린다. 그가 평생 쓴 상앗대를 내게 내민다. \"관진이 되면 이 나루도 끝이다. 끝까지 저어 주게.\"",
 [C("상앗대를 받고 방노삼을 배에 태워 마지막으로 강을 건넌다", O("방노삼은 배 위에서 한마디도 하지 않았다. 건너편에 닿자 강을 오래 돌아보았다.", alignment=AL(j=30), stats={"mind": 5})),
  C("상앗대를 받아 사공들 앞에서 나루를 맡겠다고 한다", O("사공들이 고개를 끄덕였다. 나루의 주인이 바뀌었다. 관진의 진사는 그 소식을 반기지 않았다.", alignment=AL(s=20), stats={"mind": 3}, fame=8)),
  C("상앗대를 관진의 진사에게 가져가 나루의 값을 흥정한다", O("진사가 웃으며 은자를 내밀었다. 방노삼은 그 소식을 듣고 다시는 나루에 오지 않았다.", alignment=AL(m=30), silver=100))])

ex("외전위소", "더_위소", [4, 5], "아버지의 깃발", "무너진 위소 성벽 밑에서 아버지가 들던 천호의 깃발이 나왔다. 불에 반쯤 탔다. 군호들이 그 깃발을 보고 모인다. 조정은 아직 위소를 다시 세우라는 명을 내리지 않았다.",
 [C("깃발을 기워 성벽 위에 다시 건다", O("반쯤 탄 깃발이 바닷바람에 펄럭였다. 흩어졌던 군호들이 하나둘 돌아왔다.", alignment=AL(j=30), stats={"mind": 4}, fame=10)),
  C("깃발을 조정에 보내 위소를 다시 세우라는 명을 청한다", O("깃발이 도성으로 갔다. 답은 아직 없다. 군호들은 기다리기로 했다.", alignment=AL(j=10, s=10), stats={"mind": 3})),
  C("깃발 없이 해적처럼 흑조단의 배를 친다", O("깃발 없는 배로 흑조단을 쳤다. 군호들은 해적이 된 기분이라 했다. 그래도 바다가 조금 조용해졌다.", alignment=AL(m=20, s=10), stats={"martial": 4}, silver=40))])
